/**
 * OpusFlow Vox-Pro Template — main.js
 * The complete cinematic Canvas 2D engine for Vox-style reels.
 *
 * Generated by pipeline/director.py for each film.
 * This template is fully parameterized — override FILM_DATA at the top.
 *
 * Architecture:
 *   FILM_DATA  — all film content (scenes, images, data)
 *   TIMELINE   — computed frame boundaries from voice timing
 *   render(t)  — dispatches to scene functions
 *   Each scene: (ctx, t, W, H, images) where t=0→1 within scene
 */

